const upsertBranding = `-- name: UpsertBranding :exec
INSERT INTO org_branding (organization_id, primary_color, secondary_color, motto, founded_year, portal_config)
VALUES ($1, $2, $3,
        $4, $5, $6)
ON CONFLICT (organization_id) DO UPDATE SET
  primary_color = EXCLUDED.primary_color, secondary_color = EXCLUDED.secondary_color,
  motto = EXCLUDED.motto, founded_year = EXCLUDED.founded_year,
  portal_config = EXCLUDED.portal_config
`

type UpsertBrandingParams struct {
	OrganizationID pgtype.UUID `json:"organization_id"`
	PrimaryColor   pgtype.Text `json:"primary_color"`
	SecondaryColor pgtype.Text `json:"secondary_color"`
	Motto          pgtype.Text `json:"motto"`
	FoundedYear    pgtype.Int4 `json:"founded_year"`
	PortalConfig   []byte      `json:"portal_config"`
}

func (q *Queries) UpsertBranding(ctx context.Context, arg UpsertBrandingParams) error {
	_, err := q.db.Exec(ctx, upsertBranding,
		arg.OrganizationID,
		arg.PrimaryColor,
		arg.SecondaryColor,
		arg.Motto,
		arg.FoundedYear,
		arg.PortalConfig,
	)
	return err
}

